export function FixedTableCookMeasure(value) {
  // Measure before write (docs/SPEC-TABLES.md §7.6). The header words are §19.1's.
  return TableCookWrite.variableMeasure("FixedTable", value);
}
export function FixedTableCookMeasureReason(value) {
  // Measure before write (docs/SPEC-TABLES.md §7.6). The header words are §19.1's.
  return TableCookWrite.variableReason("FixedTable", value);
}
export function FixedTableCookFrom(value, buffer, order) {
  // Measure before write (docs/SPEC-TABLES.md §7.6). The header words are §19.1's.
  return TableCookWrite.variableFrom("FixedTable", value, buffer, order);
}

export function FixedTableMeasure(v) {
  const b = TableVariableSave(TableVariableCodecs.FixedTable, v, null);
  return b === null ? -1 : b.length;
}

export function FixedTableMeasureReason(v) {
  return TableVariableMeasureReason(TableVariableCodecs.FixedTable, v);
}

export function FixedTableSave(v) {
  return TableVariableSave(TableVariableCodecs.FixedTable, v, null);
}

export function FixedTableLoad(bytes, report) {
  return TableVariableLoad(TableVariableCodecs.FixedTable, bytes, report, null);
}

export function FixedTableToJson(v) {
  return TableVariableToJson(TableVariableCodecs.FixedTable, v);
}

export function FixedTableFromJson(text, report) {
  return TableVariableFromJson(TableVariableCodecs.FixedTable, text, report);
}

export function FixedTableLoadMeasure(bytes) {
  if (bytes.length < 9) { return 1392; }
  if (bytes[0] !== TableVariableForm) { return 1392; }
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const count = dv.getBigUint64(bytes.length - 8, true);
  if (count > TableVariableEntryBound || count > BigInt(Math.floor((bytes.length - 9) / 8))) { return 1392; }
  const first = bytes.length - 8 - Number(count) * 8;
  const ids = [];
  const seen = new Set();
  for (let i = 0; i < Number(count); i++) {
    const id = dv.getBigUint64(first + i * 8, true);
    if (seen.has(id)) { return 1392; }
    seen.add(id);
    ids.push(id);
  }
  {
    const w = new TableVariableReader(bytes, 1, first);
    while (true) {
      const ref = w.leb();
      if (w.bad) { break; }
      if (ref === 0) { if (w.at !== w.end) { return 1392; } break; }
      if (ref > ids.length) { break; }
      if (w.at >= w.end) { break; }
      const kind = w.u8();
      if (!TableVariableSkip(w, kind)) { break; }
    }
  }
  const r = new TableVariableReader(bytes, 1, first);
  const at = TableVariableExtent(TableVariableCodecs.FixedTable, r, ids, 0);
  if (at < 0) { return 1392; }
  let data = TableVariableRound(1376 + at, 16);
  const nr = new TableVariableReader(bytes, 1, first);
  let present = false, bad = false, payload = null;
  while (true) {
    if (nr.at >= nr.end) { break; }
    const ref = nr.leb();
    if (nr.bad || ref === 0 || ref > ids.length) { break; }
    if (nr.at >= nr.end) { break; }
    const id = ids[ref - 1];
    const kind = nr.u8();
    if (id === TableNodeTableId) {
      present = true;
      if (kind !== 12) { bad = true; break; }
      const L = nr.leb();
      if (nr.at + L > nr.end) { bad = true; break; }
      payload = new TableVariableReader(bytes, nr.at, nr.at + L);
      nr.at += L;
      continue;
    }
    if (!TableVariableSkip(nr, kind)) { break; }
  }
  const place = TableVariableCodecs.FixedTable.place;
  const byType = place.byType;
  let records = 0;
  if (present && !bad) { payload.leb(); }
  while (!bad && present && payload !== null && payload.at < payload.end) {
    const tref = payload.leb();
    if (tref === 0 || tref > ids.length) { break; }
    const tlen = payload.leb();
    if (payload.at + tlen > payload.end) { break; }
    const tid = ids[tref - 1];
    const cc = byType.get(tid);
    if (cc !== undefined) {
      const br = new TableVariableReader(bytes, payload.at, payload.at + tlen);
      const ba = TableVariableExtent(cc, br, ids, 0);
      if (ba < 0) { return -1; }
      data += TableVariableRound(cc.sz + ba, 16);
    } else if (tid === TableStringBlobId && place.str) {
      if (tlen > 0xffffffff) { return -1; }
      data += TableVariableRound(8 + tlen + 1, 16);
    } else if (tid === TableBytesBlobId && place.bytes) {
      if (tlen > 0xffffffff) { return -1; }
      data += TableVariableRound(8 + tlen, 16);
    }
    payload.at += tlen;
    records++;
  }
  return data + (records + 1) * 16;
}

export function FixedTableLoadRetain(bytes, retain, report) {
  if (retain === null) { return FixedTableLoad(bytes, report); }
  retain.reset();
  return TableVariableLoad(TableVariableCodecs.FixedTable, bytes, report, retain);
}

export function FixedTableMeasureRetain(v, retain) {
  if (retain !== null) { retain.idUsed = 0; retain.clearPlaced(); }
  const b = TableVariableSave(TableVariableCodecs.FixedTable, v, retain);
  return b === null ? -1 : b.length;
}

export function FixedTableSaveRetain(v, retain, report) {
  if (report === null) { return null; }
  if (retain === null) { return FixedTableSave(v); }
  retain.idUsed = 0;
  retain.clearPlaced();
  const b = TableVariableSave(TableVariableCodecs.FixedTable, v, retain);
  if (b === null) { return null; }
  TableVariableRetainCountLost(retain, report);
  return b;
}

